def G(t):
    R=[("Live Dictation","Лайв Диктейшн"),("ChatGPT","Чат Джі-Пі-Ті"),("Data Controls","Дейта Контролс"),("OpenAI","Оупен Ей-Ай"),
       ("Meta Muse","Мета М'юз"),("Muse","М'юз"),("Meta","Мета"),("Reuters","Рейтер"),("AI Now","Ей-Ай Нау"),("Airbnb","Ербіенбі"),
       ("Canva Code","Канва Код"),("Canva","Канва"),("Magic Write","Меджик Райт"),("Magic Design","Меджик Дизайн"),("Magic Expand","Меджик Експенд"),
       ("Magic Edit","Меджик Едіт"),("Magic Layers","Меджик Леєрс"),("Magic Grab","Меджик Граб"),("Dream Lab","Дрім Леб"),("AI Shapes","Ей-Ай Шейпс"),
       ("Background Remover","Бекграунд Рімувер"),("AI Mode","Ей-Ай Мод"),("Robby Stein","Роббі Стайн"),("Google","Гугл"),("Gemini","Джеміні"),
       ("Signal","Сігнал"),("Android","Андроїд"),("macOS","мак-оу-ес"),("iPhone","Айфон"),("Apple","Еппл"),("Mac","Мак"),("iOS","Ай-Оу-Ес"),
       ("DOU","Доу"),("LLM","ел-ел-ем"),("ФОП","фоп"),("КМУ","Кабмін")]
    for a,b in R: t=t.replace(a,b)
    t=re.sub(r"ШІ-(\w+)", r"\1 штучного інтелекту", t)
    for a,b in [("від ШІ","від штучного інтелекту"),("з ШІ","зі штучним інтелектом"),("на ШІ","на штучний інтелект"),("у ШІ","у штучний інтелект"),("без ШІ","без штучного інтелекту")]: t=t.replace(a,b)
    return t.replace("ШІ","штучний інтелект")

